import { fmtDate, fmtDay } from "@/lib/dates";
import { nok } from "@/lib/logic";
import type { Customer, Invoice } from "@/lib/types";
import { Badge } from "./ui";

export function InvoiceStatus({ inv }: { inv: Invoice }) {
  if (inv.status === "paid") return <Badge tone="green">Paid</Badge>;
  if (inv.status === "sent") return <Badge tone="amber">Sent · due {fmtDate(inv.dueDate)}</Badge>;
  return <Badge>Draft</Badge>;
}

/** Simple invoice preview, standing in for the PDF generated by Tripletex. */
export function InvoiceView({ inv, customer }: { inv: Invoice; customer: Customer }) {
  return (
    <div className="text-sm">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <p className="font-serif text-xl font-bold tracking-[0.18em] text-brand-800">FRÆND</p>
          <p className="text-gray-500">Frænd AS · Stavanger</p>
        </div>
        <div className="text-right">
          <p className="text-lg font-semibold text-gray-900">Invoice {inv.number}</p>
          <p className="text-gray-500">Issued {fmtDate(inv.createdAt)} · Due {fmtDate(inv.dueDate)}</p>
          <div className="mt-1 flex justify-end gap-1">
            <InvoiceStatus inv={inv} />
            <Badge tone="blue">{inv.channel}</Badge>
          </div>
        </div>
      </div>
      <div className="mt-6 grid gap-4 sm:grid-cols-2">
        <div>
          <p className="text-xs uppercase tracking-wide text-gray-400">Bill to</p>
          <p className="font-medium text-gray-900">{customer.name}</p>
          <p className="text-gray-600">Org. no. {customer.orgNumber}</p>
          <p className="text-gray-600">{customer.billingAddress}</p>
        </div>
        <div className="sm:text-right">
          <p className="text-xs uppercase tracking-wide text-gray-400">Period</p>
          <p className="text-gray-900">
            {fmtDate(inv.periodStart)} – {fmtDate(inv.periodEnd)}
          </p>
          {inv.tripletexId && <p className="text-gray-500">Tripletex invoice #{inv.tripletexId}</p>}
        </div>
      </div>
      <table className="mt-6 w-full">
        <thead>
          <tr className="border-b text-left text-xs uppercase tracking-wide text-gray-400">
            <th className="py-2 font-medium">Delivery</th>
            <th className="py-2 text-right font-medium">Portions</th>
            <th className="py-2 text-right font-medium">Price</th>
            <th className="py-2 text-right font-medium">Amount</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-50">
          {inv.lines.map((l) => (
            <tr key={l.date}>
              <td className="py-1.5 text-gray-700">Corporate lunch, {fmtDay(l.date)}</td>
              <td className="py-1.5 text-right tabular-nums">{l.portions}</td>
              <td className="py-1.5 text-right tabular-nums">{nok(l.unitPrice)}</td>
              <td className="py-1.5 text-right tabular-nums">{nok(l.portions * l.unitPrice)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <div className="mt-4 ml-auto w-full max-w-xs space-y-1 border-t pt-3">
        <div className="flex justify-between text-gray-600">
          <span>Subtotal excl. VAT</span>
          <span className="tabular-nums">{nok(inv.amountExVat)}</span>
        </div>
        <div className="flex justify-between text-gray-600">
          <span>VAT</span>
          <span className="tabular-nums">{nok(inv.vat)}</span>
        </div>
        <div className="flex justify-between text-base font-semibold text-gray-900">
          <span>Total</span>
          <span className="tabular-nums">{nok(inv.total)}</span>
        </div>
      </div>
    </div>
  );
}
